-- ============================================================================
-- SteelTrack Enterprise - Complete Supabase Setup (Schema + Seed Data)
-- Run this single file in Supabase SQL Editor.
-- It creates all 33 tables, indexes, constraints, and populates all 645 products,
-- 4 branches, 52 users, 9 roles, 50 suppliers, 50 customers, and operational tables.
-- ============================================================================

CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "AuditLogs" (
    "Id" varchar NOT NULL,
    "UserId" varchar,
    "UserEmail" varchar,
    "Action" varchar NOT NULL,
    "EntityType" varchar NOT NULL,
    "EntityId" varchar,
    "Details" varchar,
    "IpAddress" varchar,
    "IsArchived" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "Category" integer NOT NULL,
    "UserAgent" varchar,
    "Status" varchar,
    "OldValue" varchar,
    "NewValue" varchar,
    CONSTRAINT "PK_AuditLogs" PRIMARY KEY ("Id")
);

CREATE TABLE "Categories" (
    "Id" varchar(36) NOT NULL,
    "Name" varchar(255) NOT NULL,
    "Description" varchar,
    "IsActive" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "Icon" varchar,
    "ColorAccent" varchar,
    "ParentCategoryId" varchar,
    "CreatedByUserId" varchar,
    CONSTRAINT "PK_Categories" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Categories_Categories_ParentCategoryId" FOREIGN KEY ("ParentCategoryId") REFERENCES "Categories" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Customers" (
    "Id" varchar NOT NULL,
    "Name" varchar NOT NULL,
    "Phone" varchar,
    "Email" varchar,
    "Address" varchar,
    "Notes" varchar,
    "IsActive" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "CustomerType" integer NOT NULL,
    "CreditLimit" numeric NOT NULL,
    "IsBlacklisted" boolean NOT NULL,
    "CreatedByUserId" varchar,
    "CustomerCode" varchar,
    "EnableCredit" boolean NOT NULL,
    "PaymentTerms" integer NOT NULL,
    "DueDays" integer NOT NULL,
    "CustomPaymentTerms" varchar,
    "AllowCheque" boolean NOT NULL,
    "IsBlocked" boolean NOT NULL,
    CONSTRAINT "PK_Customers" PRIMARY KEY ("Id")
);

CREATE TABLE "Branches" (
    "Id" varchar(36) NOT NULL,
    "Code" varchar(20) NOT NULL,
    "Name" varchar(100) NOT NULL,
    "Address" varchar(255),
    "ContactNumber" varchar(50),
    "ManagerName" varchar(100),
    "IsActive" boolean NOT NULL DEFAULT true,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_Branches" PRIMARY KEY ("Id")
);

CREATE TABLE "Roles" (
    "Id" varchar(36) NOT NULL,
    "Name" varchar(100) NOT NULL,
    "Description" varchar(500) NOT NULL,
    "BranchId" varchar(36),
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_Roles" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Roles_Branches_BranchId" FOREIGN KEY ("BranchId") REFERENCES "Branches" ("Id") ON DELETE SET NULL
);

CREATE TABLE "SalesReportVerifications" (
    "Id" varchar NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "ReportCode" varchar NOT NULL,
    "Preset" varchar NOT NULL,
    "PeriodLabel" varchar NOT NULL,
    "FromDate" timestamp with time zone NOT NULL,
    "ToDate" timestamp with time zone NOT NULL,
    "GrossSales" numeric NOT NULL,
    "NetSales" numeric NOT NULL,
    "TotalLineAmount" numeric NOT NULL,
    "PrintedAtLabel" varchar NOT NULL,
    "PrintedAtUtc" timestamp with time zone NOT NULL,
    "StoreName" varchar,
    "GeneratedByUserId" varchar,
    CONSTRAINT "PK_SalesReportVerifications" PRIMARY KEY ("Id")
);

CREATE TABLE "SteelBatches" (
    "Id" uuid NOT NULL,
    "HeatNumber" varchar NOT NULL,
    "Grade" text NOT NULL,
    "WeightInTons" double precision NOT NULL,
    "Dimensions" varchar NOT NULL,
    "Status" text NOT NULL,
    "Location" varchar NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "LastUpdated" timestamp with time zone,
    CONSTRAINT "PK_SteelBatches" PRIMARY KEY ("Id")
);

CREATE TABLE "StoreSettings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "VatEnabled" boolean NOT NULL,
    "VatRate" numeric NOT NULL,
    "PricesIncludeVat" boolean NOT NULL,
    "OutletLine" varchar NOT NULL,
    "BrandLine" varchar NOT NULL,
    "Tagline" varchar NOT NULL,
    "StoreName" varchar NOT NULL,
    "Address" varchar NOT NULL,
    "Phone" varchar NOT NULL,
    "TrustReceiptTitle" varchar NOT NULL,
    "CashReceiptTitle" varchar NOT NULL,
    "AllowCashierBarcodePrinting" boolean NOT NULL,
    CONSTRAINT "PK_StoreSettings" PRIMARY KEY ("Id")
);

CREATE TABLE "Suppliers" (
    "Id" varchar NOT NULL,
    "Name" varchar NOT NULL,
    "ContactPerson" varchar,
    "Phone" varchar,
    "Email" varchar,
    "Address" varchar,
    "IsActive" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "PaymentTerms" integer NOT NULL,
    "CustomPaymentTerms" varchar,
    "Notes" varchar,
    "Status" integer NOT NULL,
    "CreatedByUserId" varchar,
    "SupplierCode" varchar,
    "DeliveryNotes" varchar,
    "SupplierRemarks" varchar,
    CONSTRAINT "PK_Suppliers" PRIMARY KEY ("Id")
);

CREATE TABLE "Users" (
    "Id" varchar(36) NOT NULL,
    "Email" varchar(255) NOT NULL,
    "FullName" varchar(255) NOT NULL,
    "PasswordHash" varchar NOT NULL,
    "IsActive" boolean NOT NULL,
    "RoleId" varchar NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Users_Roles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "Roles" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Products" (
    "Id" varchar(36) NOT NULL,
    "Sku" varchar(100) NOT NULL,
    "Name" varchar(255) NOT NULL,
    "Description" varchar,
    "Barcode" varchar(100),
    "Size" varchar,
    "Thickness" varchar,
    "Length" varchar,
    "Grade" varchar,
    "UnitOfMeasure" varchar NOT NULL,
    "UnitPrice" numeric(18,2) NOT NULL,
    "CostPrice" numeric(18,2) NOT NULL,
    "StockQuantity" integer NOT NULL,
    "ReorderLevel" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    "CategoryId" varchar NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "Diameter" varchar,
    "Schedule" varchar,
    "Width" varchar,
    "Height" varchar,
    "MaterialType" varchar,
    "SupplierId" varchar,
    CONSTRAINT "PK_Products" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Products_Categories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "Categories" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Products_Suppliers_SupplierId" FOREIGN KEY ("SupplierId") REFERENCES "Suppliers" ("Id") ON DELETE SET NULL
);

CREATE TABLE "SupplierAttachments" (
    "Id" varchar NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "SupplierId" varchar NOT NULL,
    "FileName" varchar NOT NULL,
    "StoredFileName" varchar NOT NULL,
    "ContentType" varchar NOT NULL,
    "FileSizeBytes" bigint NOT NULL,
    "Description" varchar,
    "UploadedByUserId" varchar NOT NULL,
    CONSTRAINT "PK_SupplierAttachments" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_SupplierAttachments_Suppliers_SupplierId" FOREIGN KEY ("SupplierId") REFERENCES "Suppliers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "SupplierContacts" (
    "Id" varchar NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "SupplierId" varchar NOT NULL,
    "Name" varchar NOT NULL,
    "Role" integer NOT NULL,
    "Phone" varchar,
    "Email" varchar,
    "IsPrimary" boolean NOT NULL,
    CONSTRAINT "PK_SupplierContacts" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_SupplierContacts_Suppliers_SupplierId" FOREIGN KEY ("SupplierId") REFERENCES "Suppliers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Sales" (
    "Id" varchar(36) NOT NULL,
    "SaleNumber" varchar(100) NOT NULL,
    "UserId" varchar NOT NULL,
    "SubTotal" numeric(18,2) NOT NULL,
    "DiscountPercent" numeric(18,2) NOT NULL,
    "DiscountAmount" numeric(18,2) NOT NULL,
    "TaxMode" integer NOT NULL,
    "TaxTypeLabel" varchar,
    "TaxRate" numeric(18,2) NOT NULL,
    "TaxAmount" numeric(18,2) NOT NULL,
    "WithholdingAmount" numeric(18,2) NOT NULL,
    "ManualTaxName" varchar,
    "ManualTaxIsPercent" boolean NOT NULL,
    "ManualTaxValue" numeric(18,2) NOT NULL,
    "ManualTaxIsDeduction" boolean NOT NULL,
    "TotalAmount" numeric(18,2) NOT NULL,
    "GrossProfit" numeric(18,2) NOT NULL,
    "AmountPaid" numeric(18,2) NOT NULL,
    "ChangeAmount" numeric(18,2) NOT NULL,
    "PaymentMethod" integer NOT NULL,
    "Status" integer NOT NULL,
    "IsArchived" boolean NOT NULL,
    "CustomerName" varchar,
    "CustomerId" varchar,
    "Notes" varchar,
    "VoidReason" varchar,
    "VoidedAt" timestamp with time zone,
    "VoidedByUserId" varchar,
    "ReplacesSaleId" varchar,
    "ReplacedBySaleId" varchar,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_Sales" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Sales_Customers_CustomerId" FOREIGN KEY ("CustomerId") REFERENCES "Customers" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_Sales_Sales_ReplacedBySaleId" FOREIGN KEY ("ReplacedBySaleId") REFERENCES "Sales" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Sales_Sales_ReplacesSaleId" FOREIGN KEY ("ReplacesSaleId") REFERENCES "Sales" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Sales_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Sales_Users_VoidedByUserId" FOREIGN KEY ("VoidedByUserId") REFERENCES "Users" ("Id")
);

CREATE TABLE "StockReceivings" (
    "Id" varchar(36) NOT NULL,
    "ReceivingNumber" varchar(100) NOT NULL,
    "SupplierId" varchar NOT NULL,
    "ContainerNumber" varchar NOT NULL,
    "StockNumber" varchar NOT NULL,
    "ReferenceNumber" varchar NOT NULL,
    "DeliveryDate" timestamp with time zone NOT NULL,
    "Status" integer NOT NULL,
    "IsArchived" boolean NOT NULL,
    "Notes" varchar,
    "RequestedByUserId" varchar NOT NULL,
    "ReviewedByUserId" varchar,
    "ReviewedAt" timestamp with time zone,
    "RejectionReason" varchar,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "DeliveryReceiptNumber" varchar,
    "ApprovalNotes" varchar,
    "PurchaseOrderId" varchar,
    CONSTRAINT "PK_StockReceivings" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_StockReceivings_Suppliers_SupplierId" FOREIGN KEY ("SupplierId") REFERENCES "Suppliers" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StockReceivings_Users_RequestedByUserId" FOREIGN KEY ("RequestedByUserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StockReceivings_Users_ReviewedByUserId" FOREIGN KEY ("ReviewedByUserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "InventoryAdjustmentRequests" (
    "Id" varchar(36) NOT NULL,
    "ProductId" varchar NOT NULL,
    "SystemQuantity" integer NOT NULL,
    "ActualQuantity" integer NOT NULL,
    "Difference" integer NOT NULL,
    "Reason" varchar(500) NOT NULL,
    "Status" integer NOT NULL,
    "RequestedByUserId" varchar NOT NULL,
    "ReviewedByUserId" varchar,
    "ReviewedAt" timestamp with time zone,
    "RejectionReason" varchar,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "AdjustmentType" integer NOT NULL,
    "Notes" varchar,
    "ApprovalNotes" varchar,
    "CountingSessionId" varchar,
    CONSTRAINT "PK_InventoryAdjustmentRequests" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_InventoryAdjustmentRequests_Products_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Products" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_InventoryAdjustmentRequests_Users_RequestedByUserId" FOREIGN KEY ("RequestedByUserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_InventoryAdjustmentRequests_Users_ReviewedByUserId" FOREIGN KEY ("ReviewedByUserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "CustomerReceivables" (
    "Id" varchar(36) NOT NULL,
    "SaleId" varchar NOT NULL,
    "CustomerId" varchar,
    "CustomerName" varchar NOT NULL,
    "TotalAmount" numeric(18,2) NOT NULL,
    "PaidAmount" numeric(18,2) NOT NULL,
    "RemainingBalance" numeric(18,2) NOT NULL,
    "DueDate" timestamp with time zone NOT NULL,
    "Status" integer NOT NULL,
