    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_CustomerReceivables" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CustomerReceivables_Customers_CustomerId" FOREIGN KEY ("CustomerId") REFERENCES "Customers" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_CustomerReceivables_Sales_SaleId" FOREIGN KEY ("SaleId") REFERENCES "Sales" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "GoodsReturnSlips" (
    "Id" varchar(36) NOT NULL,
    "GrsNumber" varchar(100) NOT NULL,
    "OriginalSaleId" varchar NOT NULL,
    "ProcessedByUserId" varchar NOT NULL,
    "ReturnDate" timestamp with time zone NOT NULL,
    "TotalReturnAmount" numeric(18,2) NOT NULL,
    "Reason" varchar(500) NOT NULL,
    "GoodConditionConfirmed" boolean NOT NULL,
    "Notes" varchar,
    "IsArchived" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "OriginalInvoiceNumber" varchar,
    "CustomerName" varchar,
    "OriginalSaleDate" timestamp with time zone NOT NULL,
    "RefundMethod" integer NOT NULL,
    "Status" integer NOT NULL,
    "VoidedAt" timestamp with time zone,
    "VoidedByUserId" varchar,
    "VoidReason" varchar,
    "WorkflowKind" integer NOT NULL,
    "SubmittedAt" timestamp with time zone,
    "SubmittedByUserId" varchar,
    "ApprovedAt" timestamp with time zone,
    "ApprovedByUserId" varchar,
    "ApprovalNotes" varchar,
    "RejectedAt" timestamp with time zone,
