    CONSTRAINT "FK_GoodsReturnSlips_Users_ProcessedByUserId" FOREIGN KEY ("ProcessedByUserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_GoodsReturnSlips_Users_VoidedByUserId" FOREIGN KEY ("VoidedByUserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "SaleCheques" (
    "Id" varchar NOT NULL,
    "SaleId" varchar NOT NULL,
    "Type" integer NOT NULL,
    "Status" integer NOT NULL,
    "BankName" varchar NOT NULL,
    "Branch" varchar,
    "ChequeNumber" varchar NOT NULL,
    "AccountName" varchar NOT NULL,
    "Amount" numeric NOT NULL,
    "MaturityDate" timestamp with time zone NOT NULL,
    "ClearedAt" timestamp with time zone,
    "BouncedAt" timestamp with time zone,
    "Notes" varchar,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "BounceReason" varchar,
    "CustomerReceivableId" varchar,
    "ClearedReceivablePaymentId" varchar,
    "ReceivablePaymentId" varchar,
    "ProcessedByUserId" varchar,
    CONSTRAINT "PK_SaleCheques" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_SaleCheques_Sales_SaleId" FOREIGN KEY ("SaleId") REFERENCES "Sales" ("Id") ON DELETE CASCADE
);

CREATE TABLE "SalePayments" (
    "Id" varchar NOT NULL,
    "SaleId" varchar NOT NULL,
    "Method" integer NOT NULL,
    "Amount" numeric NOT NULL,
    "QrphReference" varchar,
    "BankName" varchar,
    "BankReferenceNumber" varchar,
    "SenderName" varchar,
    "DatePaid" timestamp with time zone,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
