    CONSTRAINT "FK_ProductBatches_Products_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Products" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ProductBatches_StockReceivings_StockReceivingId" FOREIGN KEY ("StockReceivingId") REFERENCES "StockReceivings" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_ProductBatches_Suppliers_SupplierId" FOREIGN KEY ("SupplierId") REFERENCES "Suppliers" ("Id") ON DELETE SET NULL
);

CREATE TABLE "StockReceivingAttachments" (
    "Id" varchar NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
