-- ============================================================================
-- SteelTrack Enterprise Production Database Seeder
-- Generates:
-- - 4 Branches (Davao, Mandaue, Cebu, Cagayan)
-- - 9 Roles (Owner, 4 Branch Managers, 4 Cashiers with BranchId FK)
-- - 5 Categories (Accessories, Stainless Bars, Stainless Plates, Stainless Sheets, Stainless Tubes)
-- - 52 Encrypted Users across roles and branches
-- - 645 Products from Google Sheets CSV Catalog
-- - 50+ Records per operational table (Customers, Suppliers, Batches, Receivables, Cheques, Returns, MRRs, Logs)
-- - 0 Records for Sales (Sales data excluded per instructions)
-- ============================================================================

START TRANSACTION;

-- Allow bulk inserts without foreign key ordering constraint locks
SET session_replication_role = 'replica';

-- DDL Safeguards: Ensure Branches table and Roles.BranchId exist
CREATE TABLE IF NOT EXISTS "Branches" (
    "Id" varchar(36) NOT NULL,
    "Code" varchar(20) NOT NULL,
    "Name" varchar(100) NOT NULL,
    "Address" varchar(255),
    "ContactNumber" varchar(50),
    "ManagerName" varchar(100),
    "IsActive" boolean NOT NULL DEFAULT true,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_Branches" PRIMARY KEY ("Id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Branches_Code" ON "Branches" ("Code");

CREATE TABLE IF NOT EXISTS "Roles" (
    "Id" varchar(36) NOT NULL,
    "Name" varchar(100) NOT NULL,
    "Description" varchar(500) NOT NULL,
    "BranchId" varchar(36),
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_Roles" PRIMARY KEY ("Id")
);

DO $$ 
BEGIN 
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name='Roles') THEN
        IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='Roles' AND column_name='BranchId') THEN
            ALTER TABLE "Roles" ADD COLUMN "BranchId" varchar(36);
        END IF;
    END IF;
END $$;

